<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { get,patch,post } from '../api'; const route=useRoute(),router=useRouter(),editing=!!route.params.id,clients=ref<any[]>([]),employees=ref<any[]>([]),saving=ref(false),error=ref(''); const form=ref<any>({name:'',clientId:'',ownerId:'',status:'ACTIVE',businessYear:new Date().getFullYear(),services:[]}); const labels:Record<string,string>={BIDDING:'招标代理',COST:'造价/预结算',SUPERVISION:'监理',OTHER:'其他'}; onMounted(async()=>{[clients.value,employees.value]=await Promise.all([get<any[]>('/settings/clients'),get<any[]>('/settings/employees')]);if(editing)form.value=await get(`/projects/${route.params.id}`)});function toggle(type:string){const i=form.value.services.findIndex((s:any)=>s.serviceType===type);if(i>=0)form.value.services.splice(i,1);else form.value.services.push({id:crypto.randomUUID(),serviceType:type,stage:'待开始',ownerId:form.value.ownerId||'',otherDescription:''})}async function save(){error.value='';if(!form.value.name||!form.value.clientId||!form.value.ownerId||!form.value.services.length){error.value='请填写项目名称、客户、服务类型、负责人和状态。';return}form.value.services.forEach((s:any)=>s.ownerId=s.ownerId||form.value.ownerId);saving.value=true;try{const p=editing?await patch<any>(`/projects/${route.params.id}`,form.value):await post<any>('/projects',form.value);router.push(`/projects/${p.id}`)}catch(e){error.value=(e as Error).message}finally{saving.value=false}}</script>
<template><div class="form-layout"><aside><h1 class="title">{{editing?'编辑项目':'新建项目'}}</h1><p class="subtitle">用最少信息先把项目放进系统。稍后可以补充更多资料。</p></aside><form @submit.prevent="save"><div class="form-grid"><div class="field-group full"><label>项目名称 *</label><input v-model="form.name" class="input"/></div><div class="field-group"><label>客户 *</label><select v-model="form.clientId" class="select"><option value="">请选择客户</option><option v-for="x in clients" :value="x.id">{{x.name}}</option></select></div><div class="field-group"><label>负责人 *</label><select v-model="form.ownerId" class="select"><option value="">请选择负责人</option><option v-for="x in employees.filter((x:any)=>x.active)" :value="x.id">{{x.name}}</option></select></div><div class="field-group full"><label>服务类型 *</label><div class="service-chips"><button v-for="(label,type) in labels" type="button" class="chip" :class="{active:form.services.some((s:any)=>s.serviceType===type)}" @click="toggle(String(type))">{{label}}</button></div></div><template v-for="s in form.services" :key="s.id"><div v-if="s.serviceType==='OTHER'" class="field-group full"><label>其他服务说明 *</label><input v-model="s.otherDescription" class="input" placeholder="例如：全过程咨询 / 项目管理"/></div></template><div class="field-group"><label>项目状态 *</label><select v-model="form.status" class="select"><option value="ACTIVE">在办</option><option value="COMPLETED">已完成</option><option value="CANCELLED">已取消</option></select></div><div class="field-group"><label>业务年份</label><input v-model.number="form.businessYear" class="input" type="number"/></div></div><section class="form-section"><h2 class="section-title">更多信息</h2><div class="form-grid"><div class="field-group"><label>内部项目编号</label><input v-model="form.projectNo" class="input"/></div><div class="field-group"><label>委托/开始日期</label><input v-model="form.startDate" class="input" type="date"/></div><div class="field-group"><label>计划完成日期</label><input v-model="form.plannedEndDate" class="input" type="date"/></div><div class="field-group"><label>项目/采购标的金额</label><input v-model.number="form.targetAmount" class="input" type="number" min="0"/></div><div class="field-group full"><label>备注</label><textarea v-model="form.note" class="textarea" rows="3"/></div></div></section><p v-if="error" class="error">{{error}}</p><div class="actions"><button type="button" class="button secondary" @click="router.back()">取消</button><button class="button primary" :disabled="saving">{{saving?'保存中…':editing?'保存修改':'创建项目 →'}}</button></div></form></div></template>
